#pragma once#ifdef SYSTEMREPLACE_EXPORTS#define SYSTEMREPLACE_API Q_DECL_EXPORT        #else#define SYSTEMREPLACE_API Q_DECL_IMPORT        #pragma comment( lib, "SystemReplace.lib")#endifclass SYSTEMREPLACE_API KRsuMemoryManager{  struct SWorkingKvant  {    SWorkingKvant()    {      ZeroMemory( this, sizeof(*this) );    }    BYTE *pMem;    HANDLE hVarMapping;    DWORD Size;    DWORD Pos;    SWorkingKvant *pNext;    BYTE* GetMemory( DWORD count );    DWORD LeftFree();  };  SWorkingKvant *m_pFirstBlock, *m_pActiveBlock;  DWORD m_addMBytes;public:  KRsuMemoryManager();  ~KRsuMemoryManager();protected:  KRsuMemoryManager( KRsuMemoryManager &src );  KRsuMemoryManager& operator = ( KRsuMemoryManager &src );public:  size_t Create( LPCSTR pszName, DWORD nInitialMBytes, DWORD addMBytes = 20 );  BYTE* AllocMemory( DWORD size );  void Clear();};